create table if not exists public.environmental_monitoring_records (id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects(id) on delete cascade,parameter text not null check(parameter in ('Air Quality','Water Quality','Noise Level','Soil Quality','Tree Cover','Waste Management','Biodiversity','Other')),monitoring_location text not null,measured_value numeric(16,4) not null,unit text not null,threshold_value numeric(16,4),monitoring_date date not null default current_date,status text not null default 'Within Limit' check(status in ('Within Limit','Warning','Exceedance','Pending Review')),agency text,notes text,recorded_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now());
create index if not exists environmental_monitoring_project_date_idx on public.environmental_monitoring_records(project_id,monitoring_date desc);
create index if not exists environmental_monitoring_recorded_by_idx on public.environmental_monitoring_records(recorded_by);
create table if not exists public.environmental_compliance_actions (id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects(id) on delete cascade,action_title text not null,category text not null default 'Mitigation' check(category in ('Mitigation','Permit / Clearance','Inspection Finding','Restoration','Waste Management','Other')),description text,responsible_agency text,due_date date,completed_date date,status text not null default 'Open' check(status in ('Open','In Progress','Overdue','Completed','Cancelled')),priority text not null default 'Medium' check(priority in ('Low','Medium','High','Critical')),evidence_reference text,created_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index if not exists environmental_actions_project_status_idx on public.environmental_compliance_actions(project_id,status,due_date);
create index if not exists environmental_actions_created_by_idx on public.environmental_compliance_actions(created_by);
create table if not exists public.environmental_incidents (id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects(id) on delete cascade,incident_title text not null,incident_type text not null default 'Other' check(incident_type in ('Spill / Leakage','Air Emission','Water Contamination','Noise','Tree / Habitat Damage','Waste Disposal','Worker Safety','Other')),severity text not null default 'Low' check(severity in ('Low','Moderate','High','Critical')),incident_date timestamptz not null default now(),location_description text not null,description text not null,immediate_action text,corrective_action text,status text not null default 'Reported' check(status in ('Reported','Under Investigation','Corrective Action','Closed')),reported_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index if not exists environmental_incidents_project_status_idx on public.environmental_incidents(project_id,status,incident_date desc);
create index if not exists environmental_incidents_reported_by_idx on public.environmental_incidents(reported_by);
alter table public.environmental_monitoring_records enable row level security;alter table public.environmental_compliance_actions enable row level security;alter table public.environmental_incidents enable row level security;
revoke all on public.environmental_monitoring_records,public.environmental_compliance_actions,public.environmental_incidents from anon;
grant select,insert,update,delete on public.environmental_monitoring_records,public.environmental_compliance_actions,public.environmental_incidents to authenticated;
create policy "Read environmental monitoring for accessible projects" on public.environmental_monitoring_records for select to authenticated using(private.can_access_project(project_id));
create policy "Teams record environmental monitoring" on public.environmental_monitoring_records for insert to authenticated with check(recorded_by=(select auth.uid()) and private.can_access_project(project_id) and private."current_role"()=any(array['national_admin','state_admin','project_manager','analyst']));
create policy "Teams update environmental monitoring" on public.environmental_monitoring_records for update to authenticated using(private.can_access_project(project_id) and private."current_role"()=any(array['national_admin','state_admin','project_manager','analyst'])) with check(private.can_access_project(project_id) and private."current_role"()=any(array['national_admin','state_admin','project_manager','analyst']));
create policy "Admins delete environmental monitoring" on public.environmental_monitoring_records for delete to authenticated using(private.can_access_project(project_id) and private."current_role"()=any(array['national_admin','state_admin']));
create policy "Read environmental actions for accessible projects" on public.environmental_compliance_actions for select to authenticated using(private.can_access_project(project_id));
create policy "Teams create environmental actions" on public.environmental_compliance_actions for insert to authenticated with check(created_by=(select auth.uid()) and private.can_access_project(project_id) and private."current_role"()=any(array['national_admin','state_admin','project_manager']));
create policy "Teams update environmental actions" on public.environmental_compliance_actions for update to authenticated using(private.can_access_project(project_id) and private."current_role"()=any(array['national_admin','state_admin','project_manager'])) with check(private.can_access_project(project_id) and private."current_role"()=any(array['national_admin','state_admin','project_manager']));
create policy "Admins delete environmental actions" on public.environmental_compliance_actions for delete to authenticated using(private.can_access_project(project_id) and private."current_role"()=any(array['national_admin','state_admin']));
create policy "Read environmental incidents for accessible projects" on public.environmental_incidents for select to authenticated using(private.can_access_project(project_id));
create policy "Teams report environmental incidents" on public.environmental_incidents for insert to authenticated with check(reported_by=(select auth.uid()) and private.can_access_project(project_id) and private."current_role"()=any(array['national_admin','state_admin','project_manager','analyst']));
create policy "Teams update environmental incidents" on public.environmental_incidents for update to authenticated using(private.can_access_project(project_id) and private."current_role"()=any(array['national_admin','state_admin','project_manager'])) with check(private.can_access_project(project_id) and private."current_role"()=any(array['national_admin','state_admin','project_manager']));
create policy "Admins delete environmental incidents" on public.environmental_incidents for delete to authenticated using(private.can_access_project(project_id) and private."current_role"()=any(array['national_admin','state_admin']));